//! Swift models using `IrohaSwift`'s exact numeric and JSON value types.
use super::*;

pub(super) fn render(model: &Model) -> String {
    let mut out = format!(
        "// Generated by musubi bindgen from an admitted .to artifact. Do not edit.\nimport Foundation\nimport IrohaSwift\n\npublic enum {} {{\n",
        model.namespace
    );
    out.push_str(include_str!("swift_runtime.txt"));
    writeln!(
        out,
        "public static let codeHash = {}",
        quoted(&model.code_hash)
    )
    .unwrap();
    for kind in ["View", "Kotoage", "Hajimari", "Kaizen"] {
        writeln!(out, "public struct {kind}Request<Value> {{\n public let kind = {}\n public let codeHash: String\n public let ordinal: UInt32\n public let entrypoint: String\n public let payload: ToriiJSONValue\n public let argumentSchemaJSON: String\n public let returnSchemaJSON: String\n public let decodeResult: (ToriiJSONValue) throws -> Value\n}}", quoted(kind)).unwrap();
    }
    for (id, ty) in model.types.iter().enumerate() {
        if let Some(identity) = &ty.identity {
            writeln!(out, "/// Exact signed nominal identity: {identity}").unwrap();
        }
        let name = &ty.name;
        match &ty.kind {
            Kind::Struct(fields) => product(
                &mut out,
                name,
                &fields
                    .iter()
                    .enumerate()
                    .map(|(i, (wire, child))| (field(i, wire), model.ty(*child).to_owned()))
                    .collect::<Vec<_>>(),
            ),
            Kind::Tuple(children) => product(
                &mut out,
                name,
                &children
                    .iter()
                    .enumerate()
                    .map(|(i, child)| (format!("item{i}"), model.ty(*child).to_owned()))
                    .collect::<Vec<_>>(),
            ),
            Kind::Enum(variants) => {
                writeln!(out, "public enum {name}: String {{").unwrap();
                for (i, variant) in variants.iter().enumerate() {
                    writeln!(
                        out,
                        " case v{i}_{} = {}",
                        identifier(variant),
                        quoted(variant)
                    )
                    .unwrap();
                }
                out.push_str("}\n");
            }
            kind => {
                writeln!(
                    out,
                    "public typealias {name} = {}",
                    type_expression(model, kind)
                )
                .unwrap();
            }
        }
        writeln!(
            out,
            "private static func decode{id}(_ value: ToriiJSONValue) throws -> {name} {{ {} }}",
            decode_body(model, &ty.kind, id)
        )
        .unwrap();
        writeln!(
            out,
            "private static func encode{id}(_ value: {name}) throws -> ToriiJSONValue {{ {} }}",
            encode_body(&ty.kind)
        )
        .unwrap();
    }
    for (ordinal, entry) in model.entries.iter().enumerate() {
        let name = &entry.symbol;
        product(
            &mut out,
            &format!("{name}Args"),
            &entry
                .args
                .iter()
                .enumerate()
                .map(|(i, (wire, child))| (field(i, wire), model.ty(*child).to_owned()))
                .collect::<Vec<_>>(),
        );
        let pairs = entry
            .args
            .iter()
            .enumerate()
            .map(|(i, (wire, child))| {
                format!(
                    "{}: try encode{child}(args.{})",
                    quoted(wire),
                    field(i, wire)
                )
            })
            .collect::<Vec<_>>()
            .join(", ");
        let payload = if pairs.is_empty() {
            "[:]".into()
        } else {
            format!("[{pairs}]")
        };
        writeln!(
            out,
            "/// {} entrypoint {}; signed ordinal {ordinal}.",
            entry.kind,
            quoted(&entry.name)
        )
        .unwrap();
        writeln!(out, "public static func {name}(_ args: {name}Args) throws -> {}Request<{}> {{\n return {}Request(codeHash: codeHash, ordinal: {ordinal}, entrypoint: {}, payload: .object({payload}), argumentSchemaJSON: {}, returnSchemaJSON: {}, decodeResult: decode{})\n}}", entry.kind, model.ty(entry.result), entry.kind, quoted(&entry.name), quoted(&entry.schema_json), quoted(&entry.result_schema_json), entry.result).unwrap();
    }
    out.push_str("}\n");
    out
}

fn product(out: &mut String, name: &str, fields: &[(String, String)]) {
    writeln!(out, "public struct {name} {{").unwrap();
    for (name, ty) in fields {
        writeln!(out, " public let {name}: {ty}").unwrap();
    }
    writeln!(
        out,
        " public init({}) {{",
        fields
            .iter()
            .map(|(name, ty)| format!("{name}: {ty}"))
            .collect::<Vec<_>>()
            .join(", ")
    )
    .unwrap();
    for (name, _) in fields {
        writeln!(out, "  self.{name} = {name}").unwrap();
    }
    out.push_str(" }\n}\n");
}

fn type_expression(model: &Model, kind: &Kind) -> String {
    match kind {
        Kind::Option(child) => format!("OptionValue<{}>", model.ty(*child)),
        Kind::Result(ok, err) => format!("ResultValue<{}, {}>", model.ty(*ok), model.ty(*err)),
        Kind::List(child, _) => format!("[{}]", model.ty(*child)),
        Kind::Leaf(leaf) => match leaf {
            EntrypointValueKindV1::Int => "KotodamaInt",
            EntrypointValueKindV1::Decimal => "KotodamaDecimal",
            EntrypointValueKindV1::Quantity => "KotodamaQuantity",
            EntrypointValueKindV1::Bool => "Bool",
            EntrypointValueKindV1::Json => "ToriiJSONValue",
            EntrypointValueKindV1::DataSpaceId => "UInt64",
            _ => "String",
        }
        .into(),
        Kind::Unit => "Void".into(),
        Kind::Cursor => "String".into(),
        _ => unreachable!(),
    }
}

fn decode_body(model: &Model, kind: &Kind, id: usize) -> String {
    match kind {
        Kind::Struct(fields) => {
            let keys = fields
                .iter()
                .map(|(name, _)| quoted(name))
                .collect::<Vec<_>>()
                .join(", ");
            let values = fields
                .iter()
                .enumerate()
                .map(|(i, (name, child))| {
                    format!(
                        "{}: try decode{child}(member(fields, {}))",
                        field(i, name),
                        quoted(name)
                    )
                })
                .collect::<Vec<_>>()
                .join(", ");
            format!(
                "let fields = try record(value, [{keys}]); return {}({values})",
                model.ty(id)
            )
        }
        Kind::Tuple(children) => format!(
            "let items = try array(value, {}, true); return {}({})",
            children.len(),
            model.ty(id),
            children
                .iter()
                .enumerate()
                .map(|(i, child)| format!("item{i}: try decode{child}(items[{i}])"))
                .collect::<Vec<_>>()
                .join(", ")
        ),
        Kind::Option(child) => format!(
            "let fields = try record(value); guard fields.count == 1 else {{ throw BindingError.schema }}; if let some = fields[\"some\"] {{ return .some(try decode{child}(some)) }}; guard fields[\"none\"] == .bool(true) else {{ throw BindingError.schema }}; return .none"
        ),
        Kind::Result(ok, err) => format!(
            "let fields = try record(value); guard fields.count == 1 else {{ throw BindingError.schema }}; if let ok = fields[\"ok\"] {{ return .ok(try decode{ok}(ok)) }}; if let err = fields[\"err\"] {{ return .err(try decode{err}(err)) }}; throw BindingError.schema"
        ),
        Kind::List(child, capacity) => {
            format!("return try array(value, {capacity}, false).map(decode{child})")
        }
        Kind::Enum(_) => format!(
            "guard let result = {}(rawValue: try string(value)) else {{ throw BindingError.schema }}; return result",
            model.ty(id)
        ),
        Kind::Unit => "guard value == .null else { throw BindingError.schema }; return ()".into(),
        Kind::Cursor => "return try bytes(value)".into(),
        Kind::Leaf(leaf) => format!(
            "return {}",
            match leaf {
                EntrypointValueKindV1::Int =>
                    "try KotodamaNumericV1Codec.decodeIntJSON(string(value))",
                EntrypointValueKindV1::Decimal =>
                    "try KotodamaNumericV1Codec.decodeDecimalJSON(string(value))",
                EntrypointValueKindV1::Quantity =>
                    "try KotodamaNumericV1Codec.decodeQuantityJSON(string(value))",
                EntrypointValueKindV1::Bool => "try boolean(value)",
                EntrypointValueKindV1::Json => "value",
                EntrypointValueKindV1::DataSpaceId => "try dataspace(value)",
                EntrypointValueKindV1::Blob => "try bytes(value)",
                _ => "try string(value)",
            }
        ),
    }
}

fn encode_body(kind: &Kind) -> String {
    match kind {
        Kind::Struct(fields) => {
            let pairs = fields
                .iter()
                .enumerate()
                .map(|(i, (name, child))| {
                    format!(
                        "{}: try encode{child}(value.{})",
                        quoted(name),
                        field(i, name)
                    )
                })
                .collect::<Vec<_>>()
                .join(", ");
            format!(
                "return .object([{}])",
                if pairs.is_empty() { ":" } else { &pairs }
            )
        }
        Kind::Tuple(children) => format!(
            "return .array([{}])",
            children
                .iter()
                .enumerate()
                .map(|(i, child)| format!("try encode{child}(value.item{i})"))
                .collect::<Vec<_>>()
                .join(", ")
        ),
        Kind::Option(child) => format!(
            "switch value {{ case .none: return .object([\"none\": .bool(true)]); case .some(let item): return .object([\"some\": try encode{child}(item)]) }}"
        ),
        Kind::Result(ok, err) => format!(
            "switch value {{ case .ok(let item): return .object([\"ok\": try encode{ok}(item)]); case .err(let item): return .object([\"err\": try encode{err}(item)]) }}"
        ),
        Kind::List(child, capacity) => format!(
            "guard value.count <= {capacity} else {{ throw BindingError.schema }}; return .array(try value.map(encode{child}))"
        ),
        Kind::Enum(_) => "return .string(value.rawValue)".into(),
        Kind::Unit => "return .null".into(),
        Kind::Cursor => "return .string(try bytes(.string(value)))".into(),
        Kind::Leaf(leaf) => format!(
            "return {}",
            match leaf {
                EntrypointValueKindV1::Int =>
                    ".string(KotodamaNumericV1Codec.encodeIntJSON(value))",
                EntrypointValueKindV1::Decimal =>
                    ".string(KotodamaNumericV1Codec.encodeDecimalJSON(value))",
                EntrypointValueKindV1::Quantity =>
                    ".string(KotodamaNumericV1Codec.encodeQuantityJSON(value))",
                EntrypointValueKindV1::Bool => ".bool(value)",
                EntrypointValueKindV1::Json => "value",
                EntrypointValueKindV1::DataSpaceId => ".integer(String(value))",
                EntrypointValueKindV1::Blob => ".string(try bytes(.string(value)))",
                _ => ".string(value)",
            }
        ),
    }
}
